def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    last_my, last_opp = history[-1]

    opp_d = 0
    for i in range(n):
        if history[i][1] == 'D':
            opp_d += 1

    if opp_d == n:
        return 'D'

    look = 8 if n >= 8 else n
    recent_opp_d = 0
    recent_my_d = 0
    for i in range(n - look, n):
        m, o = history[i]
        if m == 'D':
            recent_my_d += 1
        if o == 'D':
            recent_opp_d += 1

    after_d_c = 0
    after_d_d = 0
    for i in range(1, n):
        if history[i - 1][0] == 'D':
            if history[i][1] == 'C':
                after_d_c += 1
            else:
                after_d_d += 1

    after_d = after_d_c + after_d_d
    exploitable = (
        after_d >= 3 and
        after_d_c >= 2 and
        after_d_c * 2 >= after_d_d and
        opp_d <= max(3, n // 8)
    )
    retaliatory = after_d >= 3 and after_d_d >= after_d_c * 2 + 1

    high_def = (
        recent_opp_d >= 4 or
        (n >= 12 and opp_d * 2 >= n) or
        (n >= 30 and opp_d * 5 >= n * 2)
    )

    consec_opp_d = n >= 2 and history[-2][1] == 'D' and last_opp == 'D'

    if opp_d == 0:
        if n >= 96 and last_my == 'C':
            return 'D'
        if exploitable and n >= 75 and last_opp == 'C':
            return 'D'
        return 'C'

    if high_def:
        if last_opp == 'D':
            if last_my == 'D' and recent_my_d >= 3 and opp_d * 3 < n * 2:
                return 'C'
            return 'D'
        if last_my == 'D':
            return 'D' if exploitable else 'C'
        if retaliatory and recent_my_d >= 2 and opp_d * 3 < n * 2:
            return 'C'
        return 'D'

    if last_my == 'C' and last_opp == 'C' and n >= 96 and opp_d <= max(1, n // 10):
        return 'D'

    if last_opp == 'D':
        if last_my == 'D':
            if recent_opp_d >= 3 or opp_d * 3 >= n:
                return 'D'
            return 'C'
        if (
            consec_opp_d or
            recent_opp_d >= 3 or
            opp_d >= 5 or
            (n >= 20 and opp_d * 5 >= n) or
            (retaliatory and recent_opp_d >= 2)
        ):
            return 'D'
        return 'C'

    if last_my == 'D':
        if exploitable:
            return 'D'
        if n >= 90 and opp_d <= max(3, n // 8):
            return 'D'
        return 'C'

    if exploitable and n >= 70:
        return 'D'
    if opp_d >= 4 and recent_opp_d >= 2:
        return 'D'
    return 'C'
